// Image dimensions in EMU (e.g., 1.5 inch wide × 0.5 inch tall)
long widthEmu = 1371600;    // 1.5 * 914400
long heightEmu = 457200;    // 0.5 * 914400

// Build the inline drawing element
var drawing = new Drawing(
    new DW.Inline(
